mapper.select:
SELECT A.* FROM ( SELECT A.SEQ , A.STORE_CD , A.STORE_NM , A.SALE_DATE , A.LV1_CD , A.LV2_CD , A.LV3_CD , A.LV1_NM , A.LV2_NM , A.LV3_NM , A.PROD_CD , A.PROD_NM , A.DC_CD , A.DC_NM , A.DC_REASON_CD , '[' || A.DC_REASON_CD || '] ' || NVL(A.MS_COUPN_NM, A.HQ_COUPN_NM) AS DCDTL_DC_NM , A.TOT_SALE_QTY , A.TOT_SALE_AMT , A.DC_AMT , A.TOT_DC_AMT , A.REAL_SALE_AMT FROM ( SELECT '3' AS SEQ , TMS.STORE_CD , TMS.STORE_NM , TO_CHAR(TO_DATE(TSDP.SALE_DATE, 'yyyymmdd'), 'yyyy-mm-dd') AS SALE_DATE , '' AS LV1_CD , '' AS LV2_CD , '' AS LV3_CD , '' AS LV1_NM , '' AS LV2_NM , '' AS LV3_NM , '' AS PROD_CD , '' AS PROD_NM , '' AS DC_CD , '' AS DC_NM , '' AS DC_REASON_CD , '' AS HQ_COUPN_NM , '' AS MS_COUPN_NM , SUM(TSDP.TOT_SALE_QTY) AS TOT_SALE_QTY , SUM(TSDP.TOT_SALE_AMT) AS TOT_SALE_AMT , SUM(TSDPDR.DC_AMT) AS DC_AMT , SUM(TSDP.TOT_DC_AMT) AS TOT_DC_AMT , SUM(TSDP.REAL_SALE_AMT) AS REAL_SALE_AMT FROM ( SELECT TSDP.HQ_OFFICE_CD , TSDP.HQ_BRAND_CD , TSDP.STORE_CD , TSDP.SALE_DATE , TSDP.PROD_CD , SUM(TSDP.TOT_SALE_QTY) AS TOT_SALE_QTY , SUM(TSDP.TOT_SALE_AMT) AS TOT_SALE_AMT , SUM(TSDP.TOT_DC_AMT) AS TOT_DC_AMT , SUM(TSDP.REAL_SALE_AMT) AS REAL_SALE_AMT FROM TB_SL_DAILY_PROD TSDP WHERE TSDP.HQ_OFFICE_CD = #{hqOfficeCd}
AND TSDP.STORE_CD IN (${storeCdQuery})
AND TSDP.SALE_DATE BETWEEN #{startDate} AND #{endDate}
GROUP BY TSDP.HQ_OFFICE_CD , TSDP.HQ_BRAND_CD , TSDP.STORE_CD , TSDP.SALE_DATE , TSDP.PROD_CD ) TSDP , TB_SL_DAILY_PROD_DC_REASON TSDPDR , TB_MS_STORE TMS WHERE TSDP.HQ_OFFICE_CD = TSDPDR.HQ_OFFICE_CD AND TSDP.HQ_BRAND_CD = TSDPDR.HQ_BRAND_CD AND TSDP.STORE_CD = TSDPDR.STORE_CD AND TSDP.SALE_DATE = TSDPDR.SALE_DATE AND TSDP.PROD_CD = TSDPDR.PROD_CD AND TSDP.STORE_CD = TMS.STORE_CD AND TSDP.HQ_OFFICE_CD = #{hqOfficeCd}
AND TSDP.STORE_CD IN (${storeCdQuery})
AND TSDP.SALE_DATE BETWEEN #{startDate} AND #{endDate}
GROUP BY TSDP.SALE_DATE , TMS.STORE_CD , TMS.STORE_NM ) A UNION ALL SELECT A.SEQ , A.STORE_CD , A.STORE_NM , A.SALE_DATE , A.LV1_CD , A.LV2_CD , A.LV3_CD , A.LV1_NM , A.LV2_NM , A.LV3_NM , A.PROD_CD , A.PROD_NM , A.DC_CD , A.DC_NM , A.DC_REASON_CD , '[' || A.DC_REASON_CD || '] ' || NVL(A.MS_COUPN_NM, A.HQ_COUPN_NM) AS DCDTL_DC_NM , A.TOT_SALE_QTY , A.TOT_SALE_AMT , A.DC_AMT , A.TOT_DC_AMT , A.REAL_SALE_AMT FROM ( SELECT '2' AS SEQ , TMS.STORE_CD , TMS.STORE_NM , TO_CHAR(TO_DATE(TSDP.SALE_DATE, 'yyyymmdd'), 'yyyy-mm-dd') AS SALE_DATE , '' AS LV1_CD , '' AS LV2_CD , '' AS LV3_CD , '' AS LV1_NM , '' AS LV2_NM , '' AS LV3_NM , '' AS PROD_CD , '' AS PROD_NM , TSDPDR.DC_CD , ( SELECT '[' || TSDPDR.DC_CD || '] ' || NMCODE_NM FROM TB_CM_NMCODE WHERE NMCODE_GRP_CD = '041' AND NMCODE_CD = TSDPDR.DC_CD ) AS DC_NM , TSDPDR.DC_REASON_CD , ( SELECT MAX(COUPN_NM) AS COUPN_NM FROM TB_HQ_COUPON WHERE 1 = 1 AND HQ_OFFICE_CD = #{hqOfficeCd} AND PAY_CLASS_CD || COUPN_CD = TSDPDR.DC_REASON_CD ) AS HQ_COUPN_NM , ( SELECT MAX(COUPN_NM) AS COUPN_NM FROM TB_MS_COUPON WHERE 1 = 1
AND STORE_CD IN (${storeCdQuery})
AND PAY_CLASS_CD || COUPN_CD = TSDPDR.DC_REASON_CD ) AS MS_COUPN_NM , SUM(TSDP.TOT_SALE_QTY) AS TOT_SALE_QTY , SUM(TSDP.TOT_SALE_AMT) AS TOT_SALE_AMT , SUM(TSDPDR.DC_AMT) AS DC_AMT , SUM(TSDP.TOT_DC_AMT) AS TOT_DC_AMT , SUM(TSDP.REAL_SALE_AMT) AS REAL_SALE_AMT FROM ( SELECT TSDP.HQ_OFFICE_CD , TSDP.HQ_BRAND_CD , TSDP.STORE_CD , TSDP.SALE_DATE , TSDP.PROD_CD , SUM(TSDP.TOT_SALE_QTY) AS TOT_SALE_QTY , SUM(TSDP.TOT_SALE_AMT) AS TOT_SALE_AMT , SUM(TSDP.TOT_DC_AMT) AS TOT_DC_AMT , SUM(TSDP.REAL_SALE_AMT) AS REAL_SALE_AMT FROM TB_SL_DAILY_PROD TSDP WHERE TSDP.HQ_OFFICE_CD = #{hqOfficeCd}
AND TSDP.STORE_CD IN (${storeCdQuery})
AND TSDP.SALE_DATE BETWEEN #{startDate} AND #{endDate}
GROUP BY TSDP.HQ_OFFICE_CD , TSDP.HQ_BRAND_CD , TSDP.STORE_CD , TSDP.SALE_DATE , TSDP.PROD_CD ) TSDP , TB_SL_DAILY_PROD_DC_REASON TSDPDR , TB_MS_STORE TMS WHERE TSDP.HQ_OFFICE_CD = TSDPDR.HQ_OFFICE_CD AND TSDP.HQ_BRAND_CD = TSDPDR.HQ_BRAND_CD AND TSDP.STORE_CD = TSDPDR.STORE_CD AND TSDP.SALE_DATE = TSDPDR.SALE_DATE AND TSDP.PROD_CD = TSDPDR.PROD_CD AND TSDP.STORE_CD = TMS.STORE_CD AND TSDP.HQ_OFFICE_CD = #{hqOfficeCd}
AND TSDP.STORE_CD IN (${storeCdQuery})
AND TSDP.SALE_DATE BETWEEN #{startDate} AND #{endDate}
GROUP BY TSDP.SALE_DATE , TMS.STORE_CD , TMS.STORE_NM , TSDPDR.DC_CD , TSDPDR.DC_REASON_CD ) A UNION ALL SELECT '1' AS SEQ , A.STORE_CD , A.STORE_NM , TO_CHAR(TO_DATE(A.SALE_DATE, 'yyyymmdd'), 'yyyy-mm-dd') AS SALE_DATE , A.LV1_CD , A.LV2_CD , A.LV3_CD , A.LV1_NM , A.LV2_NM , A.LV3_NM , A.PROD_CD , A.PROD_NM , A.DC_CD , A.DC_NM , A.DC_REASON_CD , '[' || A.DC_REASON_CD || '] ' || NVL(A.MS_COUPN_NM, A.HQ_COUPN_NM) AS DCDTL_DC_NM , A.TOT_SALE_QTY , A.TOT_SALE_AMT , A.DC_AMT , A.TOT_DC_AMT , A.REAL_SALE_AMT FROM ( SELECT C.LV1_CD , C.LV2_CD , C.LV3_CD , C.LV1_NM , C.LV2_NM , C.LV3_NM , C.PROD_NM , TSDP.SALE_DATE , TSDP.PROD_CD , TMS.STORE_CD , TMS.STORE_NM , TSDPDR.DC_CD , ( SELECT '[' || TSDPDR.DC_CD || '] ' || NMCODE_NM FROM TB_CM_NMCODE WHERE NMCODE_GRP_CD = '041' AND NMCODE_CD = TSDPDR.DC_CD ) AS DC_NM , TSDPDR.DC_REASON_CD , ( SELECT MAX(COUPN_NM) AS COUPN_NM FROM TB_HQ_COUPON WHERE 1 = 1 AND HQ_OFFICE_CD = #{hqOfficeCd} AND PAY_CLASS_CD || COUPN_CD = TSDPDR.DC_REASON_CD ) AS HQ_COUPN_NM , ( SELECT MAX(COUPN_NM) AS COUPN_NM FROM TB_MS_COUPON WHERE 1 = 1
AND STORE_CD IN (${storeCdQuery})
AND PAY_CLASS_CD || COUPN_CD = TSDPDR.DC_REASON_CD ) AS MS_COUPN_NM , SUM(TSDP.TOT_SALE_QTY) AS TOT_SALE_QTY , SUM(TSDP.TOT_SALE_AMT) AS TOT_SALE_AMT , SUM(TSDPDR.DC_AMT) AS DC_AMT , SUM(TSDP.TOT_DC_AMT) AS TOT_DC_AMT , SUM(TSDP.REAL_SALE_AMT) AS REAL_SALE_AMT FROM ( SELECT TSDP.HQ_OFFICE_CD , TSDP.HQ_BRAND_CD , TSDP.STORE_CD , TSDP.SALE_DATE , TSDP.PROD_CD , SUM(TSDP.TOT_SALE_QTY) AS TOT_SALE_QTY , SUM(TSDP.TOT_SALE_AMT) AS TOT_SALE_AMT , SUM(TSDP.TOT_DC_AMT) AS TOT_DC_AMT , SUM(TSDP.REAL_SALE_AMT) AS REAL_SALE_AMT FROM TB_SL_DAILY_PROD TSDP WHERE TSDP.HQ_OFFICE_CD = #{hqOfficeCd}
AND TSDP.STORE_CD IN (${storeCdQuery})
AND TSDP.SALE_DATE BETWEEN #{startDate} AND #{endDate}
GROUP BY TSDP.HQ_OFFICE_CD , TSDP.HQ_BRAND_CD , TSDP.STORE_CD , TSDP.SALE_DATE , TSDP.PROD_CD ) TSDP , TB_SL_DAILY_PROD_DC_REASON TSDPDR , TB_MS_STORE TMS
, ( SELECT A.LV1_CD, A.LV2_CD, A.LV3_CD, A.LV1_NM, A.LV2_NM, A.LV3_NM, B.PROD_CD, B.PROD_NM FROM (
SELECT A.HQ_OFFICE_CD , A.PROD_CLASS_CD , DECODE (A.LV, 1, SUBSTR(A.AC_CD, INSTR(A.AC_CD, '^',1,1) + 1, LENGTH(A.AC_CD)), SUBSTR(A.AC_CD,INSTR(A.AC_CD, '^', 1, 1) + 1, INSTR(A.AC_CD, '^', 2, 1) - 2)) AS LV1_CD , DECODE (A.LV, 1, NULL, 2, SUBSTR(A.AC_CD, INSTR(A.AC_CD, '^', 2, 1) + 1, LENGTH(A.AC_CD)), 3, SUBSTR(A.AC_CD, INSTR(A.AC_CD, '^', 1, 2) + 1,(INSTR(A.AC_CD, '^', 1, 3) - 1) - INSTR(A.AC_CD, '^', 1, 2))) AS LV2_CD , DECODE (A.LV, 1, NULL, 2, NULL, 3, SUBSTR(A.AC_CD, INSTR(A.AC_CD, '^', 1, 3) + 1)) AS LV3_CD , DECODE (A.LV, 1, SUBSTR(A.AC, INSTR(A.AC, '^',1,1) + 1, LENGTH(A.AC)), SUBSTR(A.AC,INSTR(A.AC, '^', 1, 1) + 1, INSTR(A.AC, '^', 2, 1) - 2)) AS LV1_NM , DECODE (A.LV, 1, NULL, 2, SUBSTR(A.AC, INSTR(A.AC, '^', 2, 1) + 1, LENGTH(A.AC)), 3, SUBSTR(A.AC, INSTR(A.AC, '^', 1, 2) + 1,(INSTR(A.AC, '^', 1, 3) - 1) - INSTR(A.AC, '^', 1, 2))) AS LV2_NM , DECODE (A.LV, 1, NULL, 2, NULL, 3, SUBSTR(A.AC, INSTR(A.AC, '^', 1, 3) + 1)) AS LV3_NM FROM ( SELECT LEVEL LV , HQ_OFFICE_CD , PROD_CLASS_CD , SYS_CONNECT_BY_PATH(PROD_CLASS_CD, '^') AS AC_CD , SYS_CONNECT_BY_PATH(PROD_CLASS_NM, '^') AS AC FROM ( SELECT HQ_OFFICE_CD , PROD_CLASS_CD , PROD_CLASS_NM , P_PROD_CLASS_CD FROM TB_HQ_PRODUCT_CLASS WHERE HQ_OFFICE_CD = #{hqOfficeCd} ) START WITH P_PROD_CLASS_CD ='00000' AND HQ_OFFICE_CD = #{hqOfficeCd} CONNECT BY PRIOR PROD_CLASS_CD = P_PROD_CLASS_CD AND HQ_OFFICE_CD = #{hqOfficeCd} ) A
) A, TB_HQ_PRODUCT B WHERE B.HQ_OFFICE_CD = #{hqOfficeCd} AND B.PROD_CLASS_CD = A.PROD_CLASS_CD(+) ) C
, ( SELECT A.LV1_CD, A.LV2_CD, A.LV3_CD, A.LV1_NM, A.LV2_NM, A.LV3_NM, B.PROD_CD, B.PROD_NM FROM (
SELECT A.STORE_CD , A.PROD_CLASS_CD , DECODE(A.LV, 1, SUBSTR(A.AC_CD, INSTR(A.AC_CD, '^', 1, 1) + 1,LENGTH(A.AC_CD)), SUBSTR(A.AC_CD, INSTR(A.AC_CD, '^', 1, 1) + 1, INSTR(A.AC_CD, '^', 2, 1) - 2)) AS LV1_CD , DECODE(A.LV ,1, NULL ,2, SUBSTR(A.AC_CD, INSTR(A.AC_CD, '^', 2, 1) + 1, LENGTH(A.AC_CD)), 3, SUBSTR(A.AC_CD,INSTR(A.AC_CD, '^', 1, 2) + 1, (INSTR(A.AC_CD, '^', 1, 3) - 1) - INSTR(A.AC_CD, '^', 1, 2))) AS LV2_CD , DECODE(A.LV ,1 ,NULL ,2, NULL, 3, SUBSTR(A.AC_CD, INSTR(A.AC_CD, '^', 1, 3) + 1)) AS LV3_CD , DECODE(A.LV, 1, SUBSTR(A.AC, INSTR(A.AC, '^', 1, 1) + 1,LENGTH(A.AC)), SUBSTR(A.AC, INSTR(A.AC, '^', 1, 1) + 1, INSTR(A.AC, '^', 2, 1) - 2)) AS LV1_NM , DECODE(A.LV ,1, NULL ,2, SUBSTR(A.AC, INSTR(A.AC, '^', 2, 1) + 1, LENGTH(A.AC)), 3, SUBSTR(A.AC,INSTR(A.AC, '^', 1, 2) + 1, (INSTR(A.AC, '^', 1, 3) - 1) - INSTR(A.AC, '^', 1, 2))) AS LV2_NM , DECODE(A.LV ,1 ,NULL ,2, NULL, 3, SUBSTR(A.AC, INSTR(A.AC, '^', 1, 3) + 1)) AS LV3_NM FROM ( SELECT LEVEL LV , STORE_CD , PROD_CLASS_CD , SYS_CONNECT_BY_PATH(PROD_CLASS_CD, '^') AS AC_CD , SYS_CONNECT_BY_PATH(PROD_CLASS_NM, '^') AS AC FROM ( SELECT STORE_CD , PROD_CLASS_CD , PROD_CLASS_NM , P_PROD_CLASS_CD FROM TB_MS_PRODUCT_CLASS WHERE STORE_CD = #{storeCd} ) START WITH P_PROD_CLASS_CD ='00000' AND STORE_CD = #{storeCd} CONNECT BY PRIOR PROD_CLASS_CD = P_PROD_CLASS_CD AND STORE_CD = #{storeCd} ) A
) A, TB_MS_PRODUCT B WHERE B.STORE_CD = #{storeCd} AND B.PROD_CLASS_CD = A.PROD_CLASS_CD(+) ) C
WHERE TSDP.HQ_OFFICE_CD = TSDPDR.HQ_OFFICE_CD AND TSDP.HQ_BRAND_CD = TSDPDR.HQ_BRAND_CD AND TSDP.STORE_CD = TSDPDR.STORE_CD AND TSDP.SALE_DATE = TSDPDR.SALE_DATE AND TSDP.PROD_CD = TSDPDR.PROD_CD AND TSDP.PROD_CD = C.PROD_CD AND TSDP.STORE_CD = TMS.STORE_CD AND TSDP.HQ_OFFICE_CD = #{hqOfficeCd}
AND TSDP.STORE_CD IN (${storeCdQuery})
AND TSDP.SALE_DATE BETWEEN #{startDate} AND #{endDate}
GROUP BY TSDP.SALE_DATE , TMS.STORE_CD , TMS.STORE_NM , TSDPDR.DC_CD , TSDPDR.DC_REASON_CD , TSDP.PROD_CD , C.LV1_CD , C.LV2_CD , C.LV3_CD , C.LV1_NM , C.LV2_NM , C.LV3_NM , C.PROD_NM ) A ) A ORDER BY A.STORE_CD , A.STORE_NM , A.SALE_DATE DESC , A.DC_CD , A.DC_REASON_CD , A.SEQ , A.PROD_CD
